    98	    
    99	    /**
   100	     * Run the simulation from its current state for a reasonably long period,
   101	     * (1000 steps).
   102	     */
   103	    public void runLongSimulation()
   104	    {
   105	        simulate(1000);
   106	    }
   107	    
   108	    /**
   109	     * Run the simulation from its current state for the given number of steps.
   110	     * Stop before the given number of steps if it ceases to be viable.
   111	     * 
   112	     * @param numSteps The number of steps to run for.
   113	     */
   114	    public void simulate(int numSteps)
   115	    {
   116	        for(int step = 1; step <= numSteps && view.isViable(field); step++) {
   117	            simulateOneStep();
   118	            //delay(1000);   // uncomment this to run more slowly
   119	        }
   120	    }
   121	    
   122	    /**
   123	     * Run the simulation from its current state for a single step.
   124	     * Iterate over the whole field updating the state of each
   125	     * fox and rabbit.
   126	     */
   127	    public void simulateOneStep()
   128	    {
   129	        step++;
   130	        advanceSimulationState();
   131	        List<Actor> newAnimals = new ArrayList<>();
   132	        List<Actor> newPlants = new ArrayList<>();
   133	        actorsAct(plants, newPlants, weatherHandler.getWeather(), clock.getDayState());
   134	        actorsAct(animals, newAnimals, weatherHandler.getWeather(), clock.getDayState());
   135	        refreshViews();
   136	    }
   137	        
   138	    /**
   139	     * Reset the simulation to a starting position.
   140	     */
   141	    public void reset()
   142	    {
   143	        step = 0;
   144	        animals.clear();
   145	        plants.clear();
   146	        populationGenerator.populate(animals, plants);
   147	        
   148	        // Show the starting state in the view.
   149	        view.showStatus(step, field, clock, weatherHandler.getWeather());
   150	    }
   151	    
   152	    /**
   153	     * Iterates through a set of actors and makes them act, die if they are dead and subsequently adds the newborns.
   154	     * 
   155	     * @param actors List of all actors in the field.
   156	     * @param newActors List of newborns after actors act.
   157	     */
   158	    private void actorsAct(List<Actor> actors, List<Actor> newActors, Weather weather, DayState dayState) {
   159	        for(Iterator<Actor> it = actors.iterator(); it.hasNext(); ) {
   160	            Actor actor = it.next();
   161	            actor.act(newActors, weather, dayState);
   162	            if(! actor.isAlive()) {
   163	                it.remove();
   164	            }
   165	        }
   166	        actors.addAll(newActors);
   167	    }
