   169	    /**
   170	     * Advance the clock, weather, and disease state for the current step.
   171	     */
   172	    private void advanceSimulationState()
   173	    {
   174	        clock.incrementStep();
   175	        weatherHandler.updateWeather();
   176	        diseaseHandler.simulateDiseaseStep();
   177	    }
   178	
   179	    /**
   180	     * Repaint the view and dashboard after a simulation step.
   181	     */
   182	    private void refreshViews()
   183	    {
   184	        view.showStatus(step, field, clock, weatherHandler.getWeather());
   185	        if(dashboard != null) {
   186	            dashboard.updateDashboard();
   187	        }
   188	    }
